import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o as a,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Gemini Code Assist","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/code-assist.md","filePath":"products/ai-coding/gemini/code-assist.md","lastUpdated":1787044708000}'),n={name:"products/ai-coding/gemini/code-assist.md"};function o(r,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="gemini-code-assist" tabindex="-1">Gemini Code Assist <a class="header-anchor" href="#gemini-code-assist" aria-label="Permalink to &quot;Gemini Code Assist&quot;">​</a></h1><blockquote><p>Google&#39;s IDE integration. The one coding product in the family whose primary selling point is <strong>enterprise compliance</strong>.</p></blockquote><h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to &quot;What it is for&quot;">​</a></h2><p>Autonomous agents are the direction of travel, but developers still spend most of their time in VS Code or JetBrains. Code Assist fills that gap: it does not ask you to change tools or workflow, and the price is that its context boundary is whatever the editor can see.</p><p>Supported IDEs: VS Code, the JetBrains family, Android Studio.</p><h2 id="three-editions" tabindex="-1">Three editions <a class="header-anchor" href="#three-editions" aria-label="Permalink to &quot;Three editions&quot;">​</a></h2><p>The official editions are free / Standard / Enterprise. <strong>Capability is attached to the edition, not to your personal Google AI subscription</strong> — buying personal AI Pro does not turn Code Assist into the enterprise product.</p><p><strong>Since 2026-06-18 the individual free tier, and Google AI Pro / Ultra via Login with Google, no longer serve the IDE extensions.</strong> Individual developers should move to the <a href="./antigravity.html">Antigravity</a> IDE / CLI surfaces. Standard / Enterprise licences are unchanged. <a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">Official deprecation</a>.</p><p>The enterprise editions sell compliance, not extra intelligence. The official documentation opens by addressing &quot;organizations with strict data security and compliance requirements&quot; and explicitly offers:</p><ul><li>VPC Service Controls</li><li>IP indemnification</li></ul><p>If your team cannot use other AI coding tools for compliance reasons, this is the one in the family to look at.</p><p>On models, the official documentation notes that Code Assist uses Gemini 2.5 models.</p><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Notes</th></tr></thead><tbody><tr><td>Completion and generation</td><td>the main interaction shape inside the editor</td></tr><tr><td>Agent mode</td><td>understands codebase context and executes multi-step changes</td></tr><tr><td>MCP support</td><td>can connect external tools</td></tr><tr><td>Gemini CLI quota</td><td>the subscription includes Gemini CLI usage quota</td></tr></tbody></table><blockquote><p>⚠️ Older docs contained this configuration block:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;codeAssist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agentMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;autoApprove&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><p><strong>That JSON key does not exist in the official documentation.</strong> Agent mode is real, but follow the official docs for how to enable it rather than copying this.</p></blockquote><h2 id="how-to-use-it-well" tabindex="-1">How to use it well <a class="header-anchor" href="#how-to-use-it-well" aria-label="Permalink to &quot;How to use it well&quot;">​</a></h2><h3 id="specification-first" tabindex="-1">Specification first <a class="header-anchor" href="#specification-first" aria-label="Permalink to &quot;Specification first&quot;">​</a></h3><p>Do not throw a vague idea at it and expect a perfect result. Have it produce a specification, then generate against that specification:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Generate spec.md through conversation</span></span>
<span class="line"><span>   → interface constraints, Props definitions, state management strategy, edge cases</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Feed spec.md back as context</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Generate code step by step against the spec</span></span></code></pre></div><p>The real benefit is that it <strong>prevents architectural drift over a long conversation</strong>. With a written spec in context, the model has an anchor at every step; without one it slowly diverges from your original intent, and the divergence is hard to notice.</p><h3 id="pair-it-with-gemini-cli-for-debugging" tabindex="-1">Pair it with Gemini CLI for debugging <a class="header-anchor" href="#pair-it-with-gemini-cli-for-debugging" aria-label="Permalink to &quot;Pair it with Gemini CLI for debugging&quot;">​</a></h3><p>Reading an error in the editor is worse than piping the log straight over:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;analyse the build error and give the smallest fix&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;group these type errors by root cause&quot;</span></span></code></pre></div><p>The division of labour is clean: <strong>terminal work goes to <a href="./gemini-cli.html">Gemini CLI</a>, editor work goes to Code Assist.</strong></p><h2 id="common-problem-context-hallucination-across-repositories" tabindex="-1">Common problem: context hallucination across repositories <a class="header-anchor" href="#common-problem-context-hallucination-across-repositories" aria-label="Permalink to &quot;Common problem: context hallucination across repositories&quot;">​</a></h2><p><strong>Symptom</strong>: when generating logic that spans micro-frontends or services, it starts inventing API contracts.</p><p><strong>Cause</strong>: an IDE plugin&#39;s context is limited to the open files and the locally indexed workspace. If your frontend depends on type definitions in a backend repository that is not indexed locally, the model cannot see them and can only guess.</p><p><strong>Fix</strong>:</p><ol><li>Pull the relevant interface contracts and type definition files into the current workspace</li><li>Select that content and explicitly include it in context</li></ol><p><strong>The underlying judgement</strong>: if a task inherently requires understanding several repositories at once, Code Assist is the wrong tool. That case wants <a href="./antigravity.html">Antigravity</a>, which can go and read for itself.</p><h2 id="choosing-between-this-and-the-others" tabindex="-1">Choosing between this and the others <a class="header-anchor" href="#choosing-between-this-and-the-others" aria-label="Permalink to &quot;Choosing between this and the others&quot;">​</a></h2><p>The full comparison table is in the <a href="./gemini-cheatsheet.html#antigravity-vs-code-assist-vs-jules">cheatsheet</a> and is not repeated here.</p><p>The easiest way to remember it is by scope of change:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Use</th></tr></thead><tbody><tr><td>Executing and debugging in the terminal</td><td><a href="./gemini-cli.html">Gemini CLI</a></td></tr><tr><td>Completion in the editor, one file to a few nearby files</td><td>Code Assist</td></tr><tr><td>Cross-module, needs to read the code itself</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td>Hand it off and wait for a PR</td><td><a href="./jules.html">Jules</a></td></tr></tbody></table><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://developers.google.com/gemini-code-assist/docs/overview" target="_blank" rel="noreferrer">Code Assist overview</a></li><li><a href="https://developers.google.com/gemini-code-assist/docs/write-code-gemini" target="_blank" rel="noreferrer">Write code with Gemini</a></li><li><a href="https://codeassist.google" target="_blank" rel="noreferrer">Product page</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">Cheatsheet</a> — cross-product decision table</li><li><a href="./gemini-cookbook.html#_15-your-team-has-data-compliance-requirements">Cookbook</a> — the compliance recipe</li></ul>`,38)])])}const f=t(n,[["render",o]]);export{k as __pageData,f as default};
